pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Produce a non-empty Vec<String> for each input string.
            // We split on '\n' and ensure at least one element even for "".
            let mut parts: Vec<String> = if keepends {
                // Keep '\n' at the end of each line except possibly the last.
                // "a\nb\n" -> ["a\n", "b\n"]
                // "a\nb"   -> ["a\n", "b"]
                let mut out = Vec::new();
                let bytes = s.as_bytes();
                let mut start = 0usize;

                for (i, &b) in bytes.iter().enumerate() {
                    if b == b'\n' {
                        // Include the newline
                        out.push(s[start..=i].to_string());
                        start = i + 1;
                    }
                }
                if start < s.len() {
                    out.push(s[start..].to_string());
                }
                out
            } else {
                // Standard split (dropping '\n')
                // "a\nb\n" -> ["a", "b", ""] (Rust split preserves trailing empty)
                // We filter out the final empty if desired? Not required; only non-empty outer.
                s.split('\n').map(|p| p.to_string()).collect()
            };

            if parts.is_empty() {
                parts.push(String::new());
            }
            parts
        })
        .collect()
}